SELECT 'colors' AS tablo, count(*) AS mukerrer_grup, COALESCE(sum(n),0) AS fazla_satir, COALESCE(string_agg(nf,' ; ' ORDER BY n DESC),'') AS ornek FROM (SELECT "nameFold" nf, count(*)-1 n FROM "colors" WHERE "nameFold" IS NOT NULL AND "mergedIntoId" IS NULL GROUP BY 1 HAVING count(*)>1) q UNION ALL
